DROP TABLE IF EXISTS `t_char_weapon`;
CREATE TABLE `t_char_weapon`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `character_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '角色名(冗余, 便于搜索与分组)',
  `element` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '角色元素',
  `weapon_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '推荐武器名',
  `rarity` tinyint NOT NULL DEFAULT 5 COMMENT '武器星级',
  `reason` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '推荐理由',
  `sort_order` int NOT NULL DEFAULT 0 COMMENT '排序, 小的更推荐',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_cw`(`character_name` ASC, `weapon_name` ASC) USING BTREE,
  INDEX `idx_cw_character`(`character_name` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 177 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '角色武器推荐' ROW_FORMAT = DYNAMIC;

